set -e

if [ "$#" -ne 3 ]; then
    echo "Usage: $(basename "$0") <prefix> <container> <output-file>" >&2
    exit 2
fi

PREFIX=$1
CONTAINER=$2
TARGET_FILE=$3

TEMP_FILE="${TARGET_FILE}.tmp.$$"
trap 'rm -f "${TEMP_FILE}"' 0 1 2 15

cat > "${TEMP_FILE}" <<EOF
// ===========================================================================
// AUTOGENERATED FILE
// FILE IS CREATED EVERY BUILD PROCESS
// CREATED BY SCRIPT '$(basename "$0")'
// ===========================================================================

// MARK: List of Constants

/// Special enum, allowing to access some configuration constants
enum ${CONTAINER} {
EOF

# A build setting is a `NAME=value` entry whose name is a Swift-safe identifier.
# Entries with any other name are not settings and must not become constants.
/usr/bin/env | /usr/bin/sort | /usr/bin/uniq | /usr/bin/sed -n -E \
    -e 's/\\/\\\\/g' \
    -e 's/"/\\"/g' \
    -e "s/^(${PREFIX}[_A-Za-z0-9]*)=(.*)\$/\tstatic let \1 = \"\2\"/p" \
    >> "${TEMP_FILE}"

echo "}" >> "${TEMP_FILE}"
mv "${TEMP_FILE}" "${TARGET_FILE}"
